    装备: copy(equipment),
    当前可见单位: Object.fromEntries(Object.entries(visibleEnemies(stat,front)).map(([key,row]) => [key,{...unitMeta(key,row,front),...pick(row,['名称','性别','血量','攻击力','防御力','速度','状态','标签',...(row?.来源 === '其他玩家' ? [] : ['描述'])])}])),
    状态列表: copy(object(stat.状态列表)),
