  const equipment = stat => ({...Object.fromEntries(equipmentSlots.map(slot=>[slot,typeof stat?.装备?.[slot]==='string' ? stat.装备[slot] : '无'])),_前端处理:copy(object(stat?._装备处理)),_待结算:copy(Array.isArray(stat?._装备事件)?stat._装备事件:[])});
